(function inyectarMapa(){
  const svg = document.getElementById('mapaBgSvg');
  if(!svg) return;
  // insertAdjacentHTML respeta el espacio de nombres SVG; innerHTML no siempre.
  const marcadores = svg.querySelector('#mapaFibraOptica');
  if(marcadores) marcadores.insertAdjacentHTML('beforebegin', MAPA_SV_SVG);
  else svg.insertAdjacentHTML('afterbegin', MAPA_SV_SVG);
})();
